using Avalonia.Controls;using Avalonia.Layout;using SPharmacyLog.UI.Services;namespace SPharmacyLog.UI.Views;public sealed class LicenseActivationWindow:Window{TextBox key=new(){Width=460,AcceptsReturn=true,TextWrapping=Avalonia.Media.TextWrapping.Wrap,Height=100};TextBlock info=new(){TextWrapping=Avalonia.Media.TextWrapping.Wrap};public LicenseActivationWindow(){Title="S Pharmacy Log Activation";Width=560;Height=340;WindowStartupLocation=WindowStartupLocation.CenterScreen;var btn=new Button{Content="Activate",HorizontalAlignment=HorizontalAlignment.Right};btn.Click+=(_,_)=>{var r=PharmacyLicenseManager.Activate(key.Text);info.Text=r.IsValid?"License activated successfully.":$"Activation failed: {r.Check}";};Content=new StackPanel{Margin=new Avalonia.Thickness(20),Spacing=12,Children={new TextBlock{Text="Activate S Pharmacy Log",FontSize=22},new TextBlock{Text="PC code: "+PharmacyLicenseManager.PcCode},key,info,btn}};}}